process.stdin.resume();
process.stdin.setEncoding('utf8');

const chunks = [];
process.stdin.on('data', (c) => chunks.push(c));
process.stdin.on('end', () => {
  const tokens = chunks.join('').split(/\s+/).filter(Boolean);
  solve(tokens);
});

function solve(tokens) {
  if (tokens.length === 0) return;
  const N = parseInt(tokens[0], 10) || 0;
  const n = Math.min(N, tokens.length - 1);
  if (n <= 0) {
    process.stdout.write('0\n');
    return;
  }

  const h = new Int32Array(n);
  for (let i = 0; i < n; i++) h[i] = parseInt(tokens[i + 1], 10);

  // Máximo do sufixo (incluindo i)
  const sufMax = new Int32Array(n);
  let m = h[n - 1];
  for (let i = n - 1; i >= 0; i--) {
    if (h[i] > m) m = h[i];
    sufMax[i] = m;
  }

  let count = 0;
  m = h[0]; // máximo do prefixo (incluindo i)
  for (let i = 0; i < n; i++) {
    if (h[i] > m) m = h[i];
    const level = m < sufMax[i] ? m : sufMax[i];
    // secao coberta se agua tiver >= 1m de profundidade:
    // min(prefMax, sufMax) - h[i] >= 1, isto e, level > h[i]
    if (level > h[i]) count++;
  }

  process.stdout.write(String(count) + '\n');
}
